</section>

<script>
  (function() {
    var mq = window.matchMedia('(max-width: 768px)');
    function initCards(mobile) {
      var cards = document.querySelectorAll('.bl-science-card');
      cards.forEach(function(card, i) {
        if (mobile) {
          // On mobile: only first card open by default
          if (i > 0) card.removeAttribute('open');
        } else {
          // On desktop: force all open
          card.setAttribute('open', '');
        }
      });
    }
    initCards(mq.matches);
    mq.addListener(function(e) { initCards(e.matches); });
  })();
</script>

